const g=['甲','乙','丙','丁','戊','己','庚','辛','壬','癸'],z=['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'],jiang=['贵人','腾蛇','朱雀','六合','勾陈','青龙','天空','白虎','太常','玄武','太阴','天后'],short=['贵','蛇','雀','合','勾','龙','空','虎','常','玄','阴','后'],jian=['建','除','满','平','定','执','破','危','成','收','开','闭'],chang=['长生','沐浴','冠带','临官','帝旺','衰','病','死','墓','绝','胎','养'];
